package com.villofarm.config;
import io.swagger.v3.oas.models.OpenAPI;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.security.SecurityRequirement;import io.swagger.v3.oas.models.security.SecurityScheme;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;
@Configuration public class OpenApiConfig { @Bean OpenAPI villofarmOpenApi(){return new OpenAPI().info(new Info().title("Villofarm Commerce API").version("1.0").description("Products, authentication, COD ordering and administration." )).addSecurityItem(new SecurityRequirement().addList("bearerAuth")).schemaRequirement("bearerAuth",new SecurityScheme().name("bearerAuth").type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"));} }
